import React, { useState } from "react";
import {
  BrowserRouter as Router,
  Routes,
  Route,
} from "react-router-dom";
import Login from "./Login";
import AdminDashboard from "./AdminDashboard";
import UserShop from "./components/UserShop";
import CartPage from "./components/CartPage";
import CheckoutPage from "./components/CheckoutPage";
import OrderSuccess from "./components/OrderSuccess";

function App() {
  const [role, setRole] = useState(null);
  const [token, setToken] = useState(null);
  const [message, setMessage] = useState("");
  const [showLogin, setShowLogin] = useState(false); // 👈 login popup toggle

  const handleLogin = (username, password, type) => {
    if (type === "admin" && username === "admin" && password === "pass") {
      setRole("admin");
      setToken("admin_token");
      setMessage("✅ Admin login successful!");
    } else if (type === "user" && username && password) {
      setRole("user");
      setToken("user_token");
      setMessage(`👤 Welcome, ${username}!`);
    } else {
      setMessage("❌ Invalid credentials");
    }
    setShowLogin(false);
  };

  const handleLogout = () => {
    setRole(null);
    setToken(null);
    setShowLogin(false);
    setMessage("You have logged out.");
  };

  // ✅ Render based on role
  if (role === "admin") {
    return (
      <AdminDashboard
        token={token}
        onLogout={handleLogout}
        setMessage={setMessage}
      />
    );
  }

  if (role === "user") {
    return (
      <Routes>
        <Route
          path="/"
          element={
            <UserShop
              token={token}
              onLogout={handleLogout}
              setMessage={setMessage}
            />
          }
        />
        <Route path="/cart" element={<CartPage />} />
        <Route path="/checkout" element={<CheckoutPage />} />
        <Route path="/success" element={<OrderSuccess />} />
      </Routes>
    );
  }

  // ✅ Home page with login popup
  return (
    <Router>
      <div
        className="min-h-screen flex flex-col bg-cover bg-center relative"
        style={{
          backgroundImage: "url('/medical.jpg')",
        }}
      >
        <div className="absolute inset-0 bg-black/50"></div>

        {/* Navbar */}
        <nav className="relative z-10 flex justify-between items-center px-8 py-4 bg-white/10 backdrop-blur-lg border-b border-white/20 shadow-md">
          <h1 className="text-white text-2xl font-bold">💊 MediShop</h1>
          <div className="space-x-6">
            <button
              className="text-white hover:text-indigo-300 font-medium transition"
              onClick={() => setShowLogin(true)}
            >
              Login
            </button>
          </div>
        </nav>

        {/* Welcome Section */}
        <div className="relative z-10 flex-grow flex flex-col justify-center items-center text-white text-center">
          <h2 className="text-4xl font-bold mb-4 drop-shadow-lg">
            Welcome to 💊 MediShop
          </h2>
          <p className="text-lg">Your trusted online medicine store.</p>
        </div>

        {/* ✅ Login Popup */}
        {showLogin && (
          <div className="absolute inset-0 bg-black/70 flex justify-center items-center z-20">
            <div className="bg-white p-6 rounded-xl shadow-2xl w-[400px] relative">
              <button
                className="absolute top-2 right-3 text-gray-600 hover:text-black"
                onClick={() => setShowLogin(false)}
              >
                ✖
              </button>
              <Login onLogin={handleLogin} message={{ type: "", text: message }} />
            </div>
          </div>
        )}
      </div>
    </Router>
  );
}

export default App;
